function saRemoverAvaliacao2Vazia(){
    const avaliacao2Existe = excelColumns.some(c => SA_AVALIACAO2_PADRAO_COLUNAS.includes(c));
    if (!avaliacao2Existe) return false;
    const temDados = (excelData || []).some(row => SA_AVALIACAO2_PADRAO_COLUNAS.some(c => {
        const value = row && row[c];
        return value !== undefined && value !== null && String(value).trim() !== '' && String(value).trim() !== '-';
    }));
    if (temDados) return false;
    excelColumns = excelColumns.filter(c => !SA_AVALIACAO2_PADRAO_COLUNAS.includes(c));
    (excelData || []).forEach(row => SA_AVALIACAO2_PADRAO_COLUNAS.forEach(c => { if (row) delete row[c]; }));
    return true;
}
