async function loadFromStorage() {
    // O espelhamento ZIP legado só é consultado quando a cópia é aberta no próprio computador.
    // Em uma hospedagem web, os dados permanecem no IndexedDB/localStorage do navegador e não são enviados a uma API.
    const localLoopback = ['localhost', '127.0.0.1', '::1'].includes(String(window.location && window.location.hostname || '').toLowerCase());
    try { if (localLoopback && typeof window.saBackupConnect === 'function') await window.saBackupConnect(); }
    catch (err) { console.warn('O servidor de pastas local não respondeu; o navegador continuará disponível:', err); }
    try { await _saData.ready(); }
    catch (err) { console.warn('Alguns arquivos locais não puderam ser preparados:', err); }

    try {
        const { data, error } = await _saData.from('sistema_config').select('colunas, dados').eq('chave', 'principal').single();
        if (!error && data) {
            if (Array.isArray(data.colunas) && data.colunas.length > 0) excelColumns = data.colunas;
            if (Array.isArray(data.dados)) excelData = data.dados;
        }
    } catch (err) { console.error('Erro ao carregar o armazenamento local:', err); }

    // Migra a avaliação 2 vazia que existia como coluna padrão na versão anterior.
    // Se houver medições reais nela, preserva o histórico do usuário.
    saRemoverAvaliacao2Vazia();

    if (window.SA_LOCAL_SERVER_READY && typeof window.saBackupMigrateLegacyPhotos === 'function') {
        try { await window.saBackupMigrateLegacyPhotos(); }
        catch (err) { console.warn('Algumas fotos antigas continuam armazenadas no navegador:', err); }
        try { await window.saBackupSyncAll(); }
        catch (err) { console.warn('A cópia local em arquivos não foi sincronizada integralmente:', err); }
    }

    const savedConvocacao = SAStorage.getItem(STORAGE_CONVOCACAO_KEY);
    if (savedConvocacao) {
        try { selectedConvocados = new Set(JSON.parse(savedConvocacao)); } catch(e) {}
    }

    try { await carregarControlePesoStorage(); }
    catch (err) { console.warn('Não foi possível carregar o controle de peso local:', err); }
    saLastCommitted = { columns: saLocalClone(excelColumns), data: saLocalClone(excelData) };
    const initializers = [
        ['tabela de atletas', () => initExcelTable()],
        ['seletor de avaliações', () => populateEvalSelect()],
        ['botão de inclusão', () => ensureTestAddButton()],
        ['calculadora', () => ensureCalculadoraButton()],
        ['grupos', () => ensureGruposButton()],
        ['convocação', () => ensureConvocacaoModalDom()],
        ['impressão', () => ensurePrintStyles()],
        ['categorias, anos e identidade visual', () => { saSiteRefreshCategoryUI(); saSiteApplyBranding(); }],
        ['filtros de grupos', () => initGruposFilter()]
    ];
    for (const [name, initialize] of initializers) {
        try { await Promise.resolve(initialize()); }
        catch (err) { console.warn(`Falha ao inicializar ${name}:`, err); }
    }
    saUpdateTrialCounter();
}

let saveQueue = Promise.resolve();
let saLastCommitted = null;
// Temporariamente sem teto fixo para facilitar a criação da base de demonstração do vídeo.
// Para restaurar um limite depois, basta trocar null por um número; as validações abaixo continuam prontas.
const SA_MAX_ATHLETES = null;
const SA_MODE_KEY = 'sa_mode';
function saUpdateTrialCounter() {
    const counter = document.getElementById('sa-trial-counter');
    const count = Array.isArray(excelData) ? excelData.length : 0;
    if (counter) counter.textContent = count === 1 ? '1 atleta cadastrado · livre' : `${count} atletas cadastrados · livre`;
}
function saCanAddAthlete() {
    if (SAStorage.getItem(SA_MODE_KEY) !== 'free_trial') {
        alert('Para continuar, entre pelo botão Teste grátis.');
        return false;
    }
    const count = Array.isArray(excelData) ? excelData.length : 0;
    if (Number.isFinite(SA_MAX_ATHLETES) && count >= SA_MAX_ATHLETES) {
        alert(`O Teste grátis permite cadastrar até ${SA_MAX_ATHLETES} atletas. Remova um atleta para cadastrar outro.`);
        saUpdateTrialCounter();
        return false;
    }
    return true;
}
function saRestoreLastCommitted() {
    if (!saLastCommitted) return;
    excelColumns = saLocalClone(saLastCommitted.columns) || defaultColumns.slice();
    excelData = saLocalClone(saLastCommitted.data) || [];
    if (typeof renderExcelTable === 'function') renderExcelTable();
    if (typeof renderAtletasScreen === 'function') renderAtletasScreen();
    saSiteRefreshCategoryUI();
    saUpdateTrialCounter();
}
async function saveToStorage() {
    if (SAStorage.getItem(SA_MODE_KEY) !== 'free_trial') return false;
    const currentData = Array.isArray(excelData) ? excelData : [];
    if (Number.isFinite(SA_MAX_ATHLETES) && currentData.length > SA_MAX_ATHLETES) {
        alert(`O Teste grátis permite no máximo ${SA_MAX_ATHLETES} atletas. A alteração não foi salva.`);
        saRestoreLastCommitted();
        return false;
    }
    const snapshot = { columns: saLocalClone(excelColumns), data: saLocalClone(currentData) };
    const payload = {
        chave: 'principal',
        colunas: snapshot.columns,
        dados: snapshot.data,
        atualizado_em: new Date().toISOString()
    };
    saveQueue = saveQueue.catch(() => false).then(async () => {
        const { error } = await _saData.from('sistema_config').upsert(payload, { onConflict: 'chave' });
        if (error) {
            console.error('Erro ao salvar localmente:', error);
            saRestoreLastCommitted();
            alert('Não foi possível salvar no armazenamento deste dispositivo. Verifique o espaço disponível e tente novamente.');
            return false;
        }
        saLastCommitted = snapshot;
        saUpdateTrialCounter();
        saSiteRefreshCategoryUI();
        return true;
    });
    return saveQueue;
}

async function startFreeTrial() {
    try {
        if (window.SA_READY) await window.SA_READY;
        else await loadFromStorage();
        const localDb = await saLocalOpenDb();
        if (!localDb && !SAStorage.persistent) throw new Error('O navegador não disponibilizou armazenamento local persistente.');
        // Cada clique em Teste grátis inicia a tela de escolha: importar um JSON ou abrir um banco novo.
        try {
            if (navigator.storage && typeof navigator.storage.persist === 'function') navigator.storage.persist().catch(() => {});
        } catch (_) {}
        if (typeof window.saDatabaseOpenEntry !== 'function') throw new Error('A tela de escolha do banco não foi carregada. Atualize a página e tente novamente.');
        // A tela oferece somente importar um banco existente ou abrir um banco novo.
        await window.saDatabaseOpenEntry('trial');
    } catch (error) {
        console.error('Falha ao iniciar o modo local:', error);
        alert(error.message || 'Não foi possível iniciar o sistema neste navegador. Tente abrir em um navegador atualizado e fora do modo privado.');
    }
}

