function renderTrabalhoDiarioCategoriaHTML(catId){
 const cat=categoriasTrabalhoDiarioConfig()[catId];
 const estado=trabalhoDiarioEstado[catId];
 const count=aeAtletasCat(catId,'trabalho').length;
 const reg=estado&&estado.registro;
 const referencia=trabalhoFormatarDataReferenciaBR(reg?.data_referencia);
 const status=reg?`<button type="button" class="td-status ok td-status-link" onclick="abrirTrabalhoAtual('${catId}')" title="Abrir PDF atual"><strong>Atual:</strong> ${escapeHtmlJogos(reg.arquivo_nome||'PDF enviado')}<br><small>${reg.atualizado_em?new Date(reg.atualizado_em).toLocaleString('pt-BR'):''}${referencia?` • Dia: ${referencia}`:''} • Extras: <span data-ae-extra-count>${aeExtrasCat(catId,'trabalho').length}</span></small></button>`:`<div class="td-status">Nenhum trabalho enviado.</div>`;
 return `<section class="td-cat-panel" data-cat="${catId}"><h3>${cat.label}</h3><div class="td-anos">Padrão: ${cat.anos.join(', ')}</div>${status}<label class="td-file-label">PDF do trabalho<input type="file" accept="application/pdf,.pdf" onchange="selecionarArquivoTrabalhoDiario('${catId}',this)"></label><div class="td-file-name" id="td-file-${catId}">Nenhum arquivo selecionado</div><div class="td-actions"><span class="ae-recipient-count">Destinatários <b id="td-count-${catId}">${count}</b></span><button type="button" class="enviar" onclick="enviarTrabalhoDiario('${catId}')"><i class="fa-solid fa-upload"></i> Salvar/Substituir</button>${reg?`<button type="button" class="excluir-trabalho" onclick="excluirTrabalhoAtual('${catId}')"><i class="fa-solid fa-trash"></i> Excluir trabalho atual</button>`:''}</div>${renderTrabalhoExtrasHTML(catId)}</section>`;
}
function abrirTrabalhoAtual(catId){
 const reg=trabalhoDiarioEstado[catId]&&trabalhoDiarioEstado[catId].registro;
 if(!reg)return alert('Nenhum trabalho atual para abrir.');
 let url=reg.public_url||'';
 if(!url&&reg.storage_path){
  try{const {data}= _saData.storage.from(TRABALHOS_DIARIOS_BUCKET).getPublicUrl(reg.storage_path);url=data&&data.publicUrl?data.publicUrl:'';}catch(e){console.warn(e);}
 }
 const localUrl=saLocalSafeUrl(url,'');
 if(!localUrl)return alert('Este arquivo não está disponível localmente. Links externos são bloqueados nesta edição.');
 window.open(localUrl,'_blank','noopener,noreferrer');
}
async function excluirTrabalhoAtual(catId){
 const estado=trabalhoDiarioEstado[catId];
 const reg=estado&&estado.registro;
 if(!reg)return alert('Nenhum trabalho atual para excluir.');
 if(!confirm('Excluir o trabalho atual de '+(reg.categoria_label||catId)+'?'))return;
 const btn=document.querySelector(`.td-cat-panel[data-cat="${catId}"] .excluir-trabalho`);
 if(btn){btn.disabled=true;btn.textContent='Excluindo...';}
 try{
  await removerArquivoAntigoTrabalho(catId);
  const {error}=await _saData.from('trabalhos_diarios').delete().eq('categoria_id',catId);
  if(error)throw error;
  estado.registro=null;
  estado.file=null;
  alert('Trabalho atual excluído com sucesso.');
  openTrabalhoDiarioModal();
 }catch(e){
  console.error(e);
  alert('Erro ao excluir trabalho atual.');
 }finally{
  if(btn){btn.disabled=false;btn.innerHTML='<i class="fa-solid fa-trash"></i> Excluir trabalho atual';}
 }
}
