/* Atletas Extras — fonte local independente do VBolonheze Sports. */
/* Atletas Extras — fonte local independente do VBolonheze Sports. */
function criarRegistroAtletasExtras(cliente){
 const categorias=saSiteCategoriesObject();
 const modulos={trabalho:'Trabalho Diário',planejamento:'Planejamento Semanal',psr:'PSR',pse:'PSE',avd:'Avaliação Diária',fisico:'Relatório Físico',monitoramento:'Monitoramento',testes:'Testes Físicos'};
 const estado={rows:[],map:new Map(),ready:false,error:'',loadedAt:0,promise:null};
 const listeners=new Set();
 function nome(v){return String(v||'').trim().replace(/\s+/g,' ').toLowerCase();}
 function data(v){
  if(v instanceof Date && !isNaN(v)) return v.toISOString().slice(0,10);
  const s=String(v||'').trim();let m=s.match(/^(\d{4})-(\d{2})-(\d{2})/);if(m)return m[1]+'-'+m[2]+'-'+m[3];
  m=s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);if(m)return m[3]+'-'+m[2].padStart(2,'0')+'-'+m[1].padStart(2,'0');
  const n=Number(s);if(s && Number.isFinite(n)&&n>1000&&n<60000)return new Date(Math.floor(n-25569)*86400000).toISOString().slice(0,10);
  return '';
 }
 function identidade(v){const a=v&&v.id&&typeof v.id==='object'?v.id:(v||{}),nascimento=a.nascimento||a.data_nascimento||'',ano=saSiteYearFromValue(a.ano)||saSiteYearFromValue(nascimento);return {nomeCompleto:a.nomeCompleto||a.nome_completo||'',nascimento,ano,apelido:a.apelido||''};}
 function key(v){const a=identidade(v),n=nome(a.nomeCompleto),d=data(a.nascimento);return n&&d?n+'||'+d:'';}
 function categoriaAno(ano){return saSiteCategoryIdForYear(ano);}
 function origem(v){return categoriaAno(identidade(v).ano);}
 function vinculo(v){return estado.map.get(key(v))||null;}
 function ano(v,modulo){if(!estado.ready)return '';const r=vinculo(v);return r&&r[modulo]===true?String(r.ano_destino):identidade(v).ano;}
 function categoria(v,modulo){return categoriaAno(ano(v,modulo));}
 function extras(cat,modulo){if(!estado.ready)return [];return estado.rows.filter(r=>categoriaAno(r.ano_destino)===cat&&r[modulo]===true);}
 function anos(v,lista,modulo){return estado.ready&&lista.map(String).includes(ano(v,modulo));}
 function fotos(v,lista){const orig=identidade(v).ano,r=vinculo(v);return lista.map(String).includes(orig)||!!(estado.ready&&r&&lista.map(String).includes(String(r.ano_destino)));}
 function emit(changed){listeners.forEach(fn=>{try{fn(changed);}catch(e){console.warn('Atualização de extras:',e);}});}
 async function load(force=false){
  if(estado.promise)return estado.promise;
  if(!force&&estado.ready&&Date.now()-estado.loadedAt<20000)return estado.rows;
  estado.promise=(async()=>{
   try{
    let rows=[];const page=500;
    for(let from=0;;from+=page){
     const {data:result,error}=await cliente.from('atletas_extras_anos').select('*').order('atleta_key').range(from,from+page-1);
     if(error)throw error;
     rows.push(...(result||[]));if(!result||result.length<page)break;
    }
    const changed=!estado.ready||JSON.stringify(rows)!==JSON.stringify(estado.rows);
    estado.rows=rows;estado.map=new Map(rows.map(r=>[r.atleta_key,r]));estado.ready=true;estado.error='';estado.loadedAt=Date.now();emit(changed);return rows;
   }catch(e){estado.error='Não foi possível carregar Atletas Extras do armazenamento local. Verifique o espaço disponível e tente novamente.';emit(false);throw e;}
   finally{estado.promise=null;}
  })();return estado.promise;
 }
 let started=false;
 function start(){
  if(started)return;started=true;
  load().catch(e=>console.warn(estado.error,e));
  if(cliente.channel){cliente.channel('atletas-extras-anos-v2').on('postgres_changes',{event:'*',schema:'public',table:'atletas_extras_anos'},()=>load(true).catch(()=>{})).subscribe();}
  setInterval(()=>{if(!document.hidden)load(true).catch(()=>{});},30000);
  window.addEventListener('focus',()=>load(true).catch(()=>{}));
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)load(true).catch(()=>{});});
 }
 return {estado,get categorias(){return saSiteCategoriesObject();},modulos,nome,data,key,identidade,origem,vinculo,ano,categoriaAno,categoria,extras,anos,fotos,load,start,onChange:fn=>listeners.add(fn)};
}


/* Integração principal — nenhum cadastro antigo é importado. */
function aeIdRow(row){return {nomeCompleto:trabalhoNomeCompleto(row),nascimento:trabalhoNascimento(row),ano:trabalhoAnoAtleta(row),apelido:trabalhoApelido(row)};}
function aeAtletasCat(cat,modulo){
 if(!AE.estado.ready)return [];
 const mapa=new Map();
 trabalhoTodosAtletas().forEach(a=>{if(AE.categoria(a.id,modulo)===cat)mapa.set(AE.key(a.id),a);});
 // Registros cujo atleta não está mais no cadastro não geram atletas fantasmas.
 return [...mapa.values()];
}
function aeExtrasCat(cat,modulo){return aeAtletasCat(cat,modulo).filter(a=>AE.vinculo(a.id)?.[modulo]===true);}
function aeFisicoMatches(row,anos){return AE.anos(aeIdRow(row),anos.map(String),'fisico');}
function aeFisicoCat(row){return AE.categoria(aeIdRow(row),'fisico');}
function aeTextoCentral(){return '<small class="ae-source">Ano de participação definido em Atletas Extras. Cadastro e nascimento reais preservados.</small>';}
async function aeExigir(){try{await AE.load();return true;}catch(e){alert(AE.estado.error);return false;}}
let aeEditor=null,aeBusy=false;
function aeEsc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function aeNovo(){aeEditor={keys:[],anoDestino:saSiteAvailableYears()[0]||'',flags:Object.fromEntries(Object.keys(AE.modulos).map(k=>[k,true])),editKey:'',revision:null};aeRender();}
async function openAtletasExtras(){
 let m=document.getElementById('ae-modal');
 if(!m){m=document.createElement('div');m.id='ae-modal';m.className='ae-overlay';document.body.appendChild(m);m.addEventListener('click',e=>{if(e.target===m)closeAtletasExtras();});}
 m.style.display='flex';aeEditor=null;aeRender();try{await AE.load(true);}catch(e){}aeRender();
}
function closeAtletasExtras(){const m=document.getElementById('ae-modal');if(m)m.style.display='none';}



function aeEditar(key){const r=AE.estado.map.get(key);if(!r)return;aeEditor={keys:[key],anoDestino:String(r.ano_destino),flags:Object.fromEntries(Object.keys(AE.modulos).map(k=>[k,r[k]===true])),editKey:key,revision:r.revisao};aeRender();}
function aeRender(){
 const m=document.getElementById('ae-modal');if(!m||m.style.display==='none')return;
 const modulos=AE.modulos,todos=trabalhoTodosAtletas();
 const options=todos.filter(a=>AE.key(a.id)&&(!AE.vinculo(a.id)||aeEditor?.editKey===AE.key(a.id))).map(a=>{const key=AE.key(a.id),selected=aeEditor?.keys.includes(key);return '<tr class="ae-pick-row'+(selected?' ae-picked':'')+'" data-ae-search="'+aeEsc(AE.nome([a.id.apelido,a.id.ano,a.id.nomeCompleto].join(' ')))+'" onclick="aeAlternarLinha(this,event)"><td><input type="checkbox" value="'+aeEsc(key)+'" aria-label="Selecionar '+aeEsc(a.id.apelido||a.id.nomeCompleto)+' — '+aeEsc(a.id.ano)+' — '+aeEsc(a.id.nomeCompleto)+'" '+(selected?'checked ':'')+(aeEditor?.editKey?'disabled ':'')+'onchange="aeSelecionarOpcao(this)"></td><td>'+aeEsc(a.id.apelido||a.id.nomeCompleto)+'</td><td>'+aeEsc(a.id.ano)+'</td><td>'+aeEsc(a.id.nomeCompleto)+'</td></tr>';}).join('');
 const form=aeEditor?`<section class="ae-form"><h3>${aeEditor.editKey?'Editar ano e opções':'Adicionar atletas'}</h3><div class="ae-picker"><label for="ae-search">Atleta(s)</label><input id="ae-search" placeholder="Buscar por apelido, ano ou nome completo" oninput="aeFiltrarOpcoes(this.value)"><div class="ae-picker-scroll" tabindex="0" role="region" aria-label="Lista de atletas"><table id="ae-athletes" class="ae-picker-table"><colgroup><col class="ae-col-check"><col class="ae-col-apelido"><col class="ae-col-ano"><col></colgroup><thead><tr><th scope="col"><span class="ae-sr-only">Selecionar</span></th><th scope="col">Apelido</th><th scope="col">Ano</th><th scope="col">Nome completo</th></tr></thead><tbody>${options}</tbody></table></div><p id="ae-no-matches" ${options?'hidden':''}>Nenhum atleta encontrado.</p></div><label>Ler como atleta do ano<select id="ae-destino" onchange="aeEditor.anoDestino=this.value">${aeAnosDestino().map(y=>`<option value="${y}" ${y===aeEditor.anoDestino?'selected':''}>${y} — ${AE.categorias[AE.categoriaAno(y)]?.label||''}</option>`).join('')}</select></label><p>Marcada: usa o ano escolhido. Desmarcada: usa o ano real. Nenhuma informação do cadastro é alterada.</p><div class="ae-flags">${Object.entries(modulos).map(([k,label])=>`<label><input type="checkbox" data-ae-flag="${k}" ${aeEditor.flags[k]?'checked':''} onchange="aeEditor.flags['${k}']=this.checked">${label}</label>`).join('')}</div><div class="ae-actions"><button type="button" onclick="aeEditor=null;aeRender()">Cancelar</button><button type="button" class="ae-primary" ${aeBusy?'disabled':''} onclick="aeSalvar()">${aeBusy?'Salvando…':'Salvar'}</button></div></section>`:'';
 const rows=AE.estado.rows.map(r=>{const key=encodeURIComponent(r.atleta_key).replace(/'/g,'%27');const effects=Object.entries(modulos).map(([k,label])=>'<span class="'+(r[k]?'ae-on':'ae-off')+'">'+aeEsc(label)+': '+aeEsc(r[k]?r.ano_destino:r.ano)+'</span>').join('');return `<article class="ae-row"><h3>${aeEsc(r.apelido||r.nome_completo)}<small>Ano real ${aeEsc(r.ano)} → ler como ${aeEsc(r.ano_destino)}</small></h3><p>${aeEsc(r.nome_completo)}</p><div class="ae-effects">${effects}</div><div class="ae-actions"><button onclick="aeEditar(decodeURIComponent('${key}'))">Editar opções</button><button ${aeBusy?'disabled':''} onclick="aeRemover(decodeURIComponent('${key}'))">Remover vínculo</button></div></article>`;}).join('');
 m.innerHTML=`<div class="ae-card"><button class="ae-close" aria-label="Fechar" onclick="closeAtletasExtras()">×</button><h2>Atletas Extras</h2><p>Escolha como o atleta será agrupado em cada módulo. Nascimento, idade, cadastro e dados individuais permanecem reais.</p><p><b>Atletas e Convocação:</b> sempre no ano real. <b>Fotos:</b> aparece no ano real e no escolhido, sem duplicar o cadastro.</p>${AE.estado.error?'<div class="ae-error">'+aeEsc(AE.estado.error)+'</div>':''}${!AE.estado.ready?'<p>Carregando os dados locais…</p>':''}<div class="ae-actions"><button onclick="AE.load(true).then(aeRender).catch(aeRender)">Atualizar</button><button class="ae-primary" ${!AE.estado.ready?'disabled':''} onclick="aeNovo()">+ Adicionar atletas</button></div>${form}<div class="ae-list">${rows||(AE.estado.ready?'<p>Nenhum atleta extra cadastrado. Todos permanecem nos anos reais.</p>':'')}</div></div>`;
}
function aeFiltrarOpcoes(text){const q=AE.nome(text);let count=0;document.querySelectorAll('#ae-athletes tbody tr').forEach(row=>{row.hidden=!!q&&!row.dataset.aeSearch.includes(q);if(!row.hidden)count++;});const empty=document.getElementById('ae-no-matches');if(empty)empty.hidden=count>0;}
async function aeSalvar(){
 if(aeBusy||!aeEditor)return;const d=aeEditor,keys=d.keys.slice(),ano=String(d.anoDestino);
 if(!keys.length)return alert('Selecione ao menos um atleta.');if(!aeAnosDestino().includes(ano))return alert('Escolha o ano de destino.');
 const all=trabalhoTodosAtletas(),ids=keys.map(k=>all.find(a=>AE.key(a.id)===k));if(ids.some(a=>!a))return alert('Atleta não encontrado no cadastro.');if(ids.some(a=>String(a.id.ano)===ano))return alert('Escolha um ano diferente do ano real dos atletas selecionados.');
 aeBusy=true;aeRender();try{
  const values=ids.map(a=>({atleta_key:AE.key(a.id),nome_completo:a.id.nomeCompleto,nascimento:AE.data(a.id.nascimento),ano:String(a.id.ano),apelido:a.id.apelido||'',ano_destino:ano,...d.flags}));
  const q=d.editKey?_saData.from('atletas_extras_anos').update(values[0]).eq('atleta_key',d.editKey).eq('revisao',d.revision):_saData.from('atletas_extras_anos').insert(values);
  const {data,error}=await q.select('*');if(error)throw error;if(!data?.length)throw new Error('O vínculo mudou em outro aparelho. Atualize antes de salvar.');aeEditor=null;await AE.load(true);
 }catch(e){alert('Não foi possível salvar. '+e.message);}finally{aeBusy=false;aeRender();}
}
async function aeRemover(key){
 if(aeBusy)return;const r=AE.estado.map.get(key);if(!r)return;if(!confirm('Remover somente o vínculo de '+(r.apelido||r.nome_completo)+'? O atleta volta ao ano real. Nenhum dado individual será apagado.'))return;
 aeBusy=true;try{const {data,error}=await _saData.from('atletas_extras_anos').delete().eq('atleta_key',key).eq('revisao',r.revisao).select('atleta_key');if(error)throw error;if(!data?.length)throw new Error('Vínculo alterado em outro aparelho. Atualize.');if(aeEditor?.editKey===key)aeEditor=null;await AE.load(true);}catch(e){alert(e.message);}finally{aeBusy=false;aeRender();}
}
function aeRefreshViews(changed){
 let banner=document.getElementById('ae-sync-status');
 if(!banner){banner=document.createElement('div');banner.id='ae-sync-status';banner.className='ae-sync-status';document.body.appendChild(banner);}
 banner.hidden=!AE.estado.error;banner.textContent=AE.estado.error;
 if(!changed)return;aeRender();
 const visible=id=>{const e=document.getElementById(id);return e&&e.style.display!=='none';};
 if(visible('relatorio-psrpse-modal'))renderRelatorioPsrPse();
 if(visible('avd-modal'))aeAvdAtualizarLista();
 if(visible('avd-rel-modal')&&avdRelState.cat)carregarAvdRelatorio();
 if(visible('relatorios-modal'))renderRelatoriosTabela();
 if(visible('relatorio-visualizacao-modal'))renderRelatorioVisualizacaoDocumento();
 if(document.querySelector('#testes-screen.active'))aeAtualizarTestesSemGravar();
 if(visible('monitoramento-carga-modal'))renderMonitoramentoCargaModal();
 if(visible('fotos-atletas-modal')&&window.__aeFotoCategoria)renderFotosCategoria(window.__aeFotoCategoria);
 if(document.getElementById('grupo-categoria-select'))calcularMediaCategoria();
 ['trabalho','planejamento'].forEach(mod=>Object.keys(AE.categorias).forEach(c=>{const el=document.getElementById((mod==='trabalho'?'td-count-':'ps-count-')+c);if(el){el.textContent=aeAtletasCat(c,mod).length;const panel=el.closest('.td-cat-panel');const extras=panel?.querySelector('.td-extras');if(extras)extras.outerHTML=mod==='trabalho'?renderTrabalhoExtrasHTML(c):renderPlanejamentoExtrasHTML(c);const count=panel?.querySelector('[data-ae-extra-count]');if(count)count.textContent=aeExtrasCat(c,mod).length;}}));
}
function aeBoot(){AE.onChange(aeRefreshViews);AE.start();}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',aeBoot);else setTimeout(aeBoot,0);

function aeAnosDestino(){return [...new Set(Object.values(AE.categorias).flatMap(c=>c.anos))].sort();}
function aeSelecionarOpcao(input){
 if(!aeEditor||aeEditor.editKey||input.disabled)return;
 const keys=new Set(aeEditor.keys);if(input.checked)keys.add(input.value);else keys.delete(input.value);aeEditor.keys=[...keys];input.closest('tr').classList.toggle('ae-picked',input.checked);
}
function aeAlternarLinha(row,event){if(event.target.closest('input'))return;const input=row.querySelector('input[type=checkbox]');if(input&&!input.disabled){input.checked=!input.checked;aeSelecionarOpcao(input);}}
function mcAnoReal(row){const base=mcAtletaBase(row);return base?String(aeIdRow(base).ano||''):String(AE.data(row?.nascimento).slice(0,4)||row?.ano||'');}
// Leitura do histórico: nenhuma movimentação, UPDATE ou DELETE de avaliações.
function aeNotaKey(r){if(AE.key(r))return AE.key(r);const p=String(r.atleta_key||'').split('||');return AE.key({nomeCompleto:p[0],nascimento:p.slice(1).join('||')});}
async function aeAvdLerTabela(tabela,de,ate){
 const all=[],page=500;for(let from=0;;from+=page){let q=_saData.from(tabela).select('*').order('data').order('categoria');if(tabela==='avaliacao_diaria_notas')q=q.order('atleta_key');if(de)q=q.gte('data',de);if(ate)q=q.lte('data',ate);const {data,error}=await q.range(from,from+page-1);if(error)throw error;all.push(...(data||[]));if(!data||data.length<page)break;}return all;
}
function aeAvdNotasParaCategoria(rows,cat){
 const atletas=new Map(avdAtletasCat(cat).map(a=>[AE.key(a.id),a]));const escolhidas=new Map();
 for(const r of rows){const canonical=aeNotaKey(r),a=atletas.get(canonical);if(!a)continue;const date=String(r.data||'').slice(0,10),key=canonical+'|'+date,prev=escolhidas.get(key);
  // Uma nota por atleta/dia. Última edição vence; empate prefere a categoria atual.
  const stamp=String(r.atualizado||r.atualizado_em||''),old=String(prev?.atualizado||prev?.atualizado_em||'');
  if(!prev||stamp>old||(stamp===old&&r.categoria===cat&&prev.categoria!==cat))escolhidas.set(key,{...r,atleta_key:avdChaveId(a.id),data:date});
 }
 return [...escolhidas.values()];
}
async function aeAvdAtualizarLista(){
 const cat=avdState.cat,date=avdState.data;const ta=document.getElementById('avd-anotacao');if(ta)avdState.anotacao=ta.value;avdRender();if(!cat||!date)return;
 try{const rows=aeAvdNotasParaCategoria(await aeAvdLerTabela('avaliacao_diaria_notas',date,date),cat);if(avdState.cat!==cat||avdState.data!==date)return;for(const r of rows){if(!Object.prototype.hasOwnProperty.call(avdState.notas,r.atleta_key))avdState.notas[r.atleta_key]=Number(r.nota);if(!Object.prototype.hasOwnProperty.call(avdState.anularPse,r.atleta_key))avdState.anularPse[r.atleta_key]=r.anular_pse===true||r.anular_pse==='true';}const t=document.getElementById('avd-anotacao');if(t)avdState.anotacao=t.value;avdRender();}catch(e){console.warn('Histórico AVD não sincronizado:',e);}
}
function aeAtualizarTestesSemGravar(){
 // O renderizador legado calcula campos derivados ao desenhar. Um vínculo novo
 // não pode alterar nem esses campos em memória: restaura os mesmos objetos.
 const rows=(excelData||[]).map(r=>[r,{...r}]),cols=excelColumns.slice();
 try{renderPfTable();}finally{for(const [row,saved]of rows){Object.keys(row).forEach(k=>{if(!(k in saved))delete row[k];});Object.assign(row,saved);}excelColumns.splice(0,excelColumns.length,...cols);}
}

let avdRelRequest=0;
function avdRelSetTipo(tipo){
 if(!['treino','treino_jogo','jogo'].includes(tipo))return;
 avdRelState.tipo=tipo;
 if(avdRelState.cat)return carregarAvdRelatorio();
 renderAvdRelatorio();
}

/* === CONVOCAÇÃO MANUAL — fluxo independente da convocação original ===
   Estado local e tabela armazenamento local exclusivos; não usa selectedConvocados,
   STORAGE_CONVOCACAO_KEY, sa_escalacao_v1 ou a tabela convocacoes. */
const MANUAL_CONVOCACAO_STORAGE_KEY = 'sa_convocacao_manual_draft_v1';
const MANUAL_CONVOCACAO_TABLE = 'convocacoes_manuais';
let manualConvocacaoState = null;
let manualConvocacaoIdCounter = 0;

function manualConvocacaoNovoId(){
 manualConvocacaoIdCounter += 1;
 return 'mc_' + Date.now().toString(36) + '_' + manualConvocacaoIdCounter.toString(36) + '_' + Math.random().toString(36).slice(2,7);
}
function manualConvocacaoEscapar(valor){
 return String(valor ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}
function manualConvocacaoCoord(valor){
 const n=parseFloat(String(valor ?? '').replace('%',''));
 return Number.isFinite(n) && n>=2 && n<=98 ? n+'%' : '';
}
function manualConvocacaoNormalizarEstado(raw){
 const src=raw && typeof raw==='object' ? raw : {};
 const seen=new Set();
 const atletas=(Array.isArray(src.atletas)?src.atletas:[]).map(a=>{
  const item=a && typeof a==='object'?a:{};
  let id=String(item.id||manualConvocacaoNovoId());
  if(seen.has(id)) id=manualConvocacaoNovoId();
  seen.add(id);
  return {
   id,
   nome:String(item.nome ?? item.name ?? '').trim().slice(0,120),
   numero:String(item.numero ?? item.number ?? '').trim().slice(0,3),
   status:item.status==='titular'?'titular':'reserva',
   left:manualConvocacaoCoord(item.left),
   top:manualConvocacaoCoord(item.top)
  };
 });
 const j=src.jogo && typeof src.jogo==='object' ? src.jogo : {};
 const c=Array.isArray(src.comissao)?src.comissao:[];
 const uniformeRaw=String(src.uniforme||'base_vermelha').toLowerCase();
 const uniforme=['base','base_vermelha','base_branca','base_preta_branca'].includes(uniformeRaw)
  ? (uniformeRaw==='base'?'base_vermelha':uniformeRaw)
  : 'base_vermelha';
 return {
  salvoComo:String(src.salvoComo ?? src.nome ?? '').trim(),
  uniforme,
  atletas,
  jogo:{
   horario:String(j.horario||''), local:String(j.local||''), data:String(j.data||''),
   adversario:String(j.adversario||''), apresentacao:String(j.apresentacao||''),
   prelecao:String(j.prelecao||''), aquecimento:String(j.aquecimento||'')
  },
  comissao:[0,1,2,3].map(i=>String(c[i]||''))
 };
}
function manualConvocacaoEstadoInicial(){
 return manualConvocacaoNormalizarEstado({atletas:[{id:manualConvocacaoNovoId(),nome:'',numero:'',status:'reserva'}]});
}
function manualConvocacaoObterEstado(){
 if(manualConvocacaoState)return manualConvocacaoState;
 try{
  const salvo=JSON.parse(SAStorage.getItem(MANUAL_CONVOCACAO_STORAGE_KEY)||'null');
  if(salvo && typeof salvo==='object'){
   manualConvocacaoState=manualConvocacaoNormalizarEstado(salvo);
   return manualConvocacaoState;
  }
 }catch(e){console.warn('Rascunho da convocação manual não pôde ser lido:',e);}
 manualConvocacaoState=manualConvocacaoEstadoInicial();
 return manualConvocacaoState;
}
function manualConvocacaoSalvarRascunho(){
 if(!manualConvocacaoState)return;
 try{SAStorage.setItem(MANUAL_CONVOCACAO_STORAGE_KEY,JSON.stringify(manualConvocacaoState));}
 catch(e){console.warn('Rascunho da convocação manual não pôde ser salvo:',e);}
}
function manualConvocacaoAbrir(){
 manualConvocacaoObterEstado();
 let modal=document.getElementById('convocacao-manual-modal');
 if(!modal){
  modal=document.createElement('div');
  modal.id='convocacao-manual-modal';
  modal.className='manual-convocacao-overlay';
  modal.setAttribute('role','dialog');
  modal.setAttribute('aria-modal','true');
  modal.setAttribute('aria-label','Convocação Manual');
  modal.addEventListener('click',e=>{if(e.target===modal)manualConvocacaoFechar();});
  document.body.appendChild(modal);
 }
 manualConvocacaoRenderizarLista();
 modal.style.display='flex';
}
function manualConvocacaoFechar(){
 const campo=document.getElementById('campo-convocacao-manual-modal');
 if(campo && campo.style.display!=='none')manualConvocacaoCapturarCampo();
 ['convocacao-manual-modal','campo-convocacao-manual-modal','manual-convocacao-salvar-modal','manual-convocacao-carregar-modal','manual-convocacao-excluir-modal'].forEach(id=>{const el=document.getElementById(id);if(el)el.style.display='none';});
}
function manualConvocacaoRenderizarLista(){
 const modal=document.getElementById('convocacao-manual-modal');
 if(!modal)return;
 const st=manualConvocacaoObterEstado();
 const rows=st.atletas.map((a,i)=>{
  const id=manualConvocacaoEscapar(a.id);
  const radioName='manual-status-'+id;
  return `<div class="manual-convocacao-row" data-manual-row="${id}">
   <label class="manual-convocacao-name-label"><span class="manual-convocacao-mobile-label">Nome do atleta</span><input class="manual-convocacao-name" type="text" maxlength="120" autocomplete="off" placeholder="Nome do atleta" aria-label="Nome do atleta ${i+1}" data-manual-id="${id}" value="${manualConvocacaoEscapar(a.nome)}"></label>
   <label class="manual-convocacao-number-label"><span class="manual-convocacao-mobile-label">Nº da camiseta</span><input class="manual-convocacao-number" type="number" min="1" max="99" step="1" inputmode="numeric" placeholder="#" aria-label="Número da camiseta do atleta ${i+1}" data-manual-id="${id}" value="${manualConvocacaoEscapar(a.numero)}"></label>
   <label class="manual-convocacao-status-option" title="Definir ${manualConvocacaoEscapar(a.nome||'atleta '+(i+1))} como titular"><input class="manual-convocacao-status" type="radio" name="${radioName}" value="titular" data-manual-id="${id}" ${a.status==='titular'?'checked':''}><span>Titular</span></label>
   <label class="manual-convocacao-status-option" title="Definir ${manualConvocacaoEscapar(a.nome||'atleta '+(i+1))} como reserva"><input class="manual-convocacao-status" type="radio" name="${radioName}" value="reserva" data-manual-id="${id}" ${a.status!=='titular'?'checked':''}><span>Reserva</span></label>
   <button type="button" class="manual-convocacao-remove" data-manual-remove="${id}" aria-label="Remover atleta ${i+1}" title="Remover atleta">×</button>
  </div>`;
 }).join('');
 const total=st.atletas.filter(a=>a.nome.trim()||a.numero.trim()).length;
 modal.innerHTML=`<div class="manual-convocacao-card">
  <header class="manual-convocacao-header"><div><h2>CONVOCAÇÃO MANUAL</h2><p>Digite nome e número e marque cada atleta como titular ou reserva. A lista é independente da convocação normal.</p></div><button type="button" class="manual-convocacao-close" aria-label="Fechar" onclick="manualConvocacaoFechar()">×</button></header>
  <div class="manual-convocacao-toolbar"><button type="button" onclick="manualConvocacaoAbrirCarregar()">📂 Carregar</button><button type="button" class="manual-convocacao-delete" onclick="manualConvocacaoAbrirExcluir()">🗑 Excluir Convocação</button><button type="button" class="manual-convocacao-clear" onclick="manualConvocacaoLimpar()">Limpar Convocação</button><span class="manual-convocacao-saved-label">${st.salvoComo?'Salva como: '+manualConvocacaoEscapar(st.salvoComo):'Rascunho manual'}</span></div>
  <div class="manual-convocacao-table-head"><span>Nome do atleta</span><span>Nº da camiseta</span><span>Titular</span><span>Reserva</span><span></span></div>
  <div class="manual-convocacao-list" id="manual-convocacao-list">${rows||'<div class="manual-convocacao-empty">Nenhum atleta informado. Use “Adicionar atleta” para começar.</div>'}</div>
  <div class="manual-convocacao-add-row"><button type="button" onclick="manualConvocacaoAdicionarAtleta()">＋ Adicionar atleta</button><span>Atletas preenchidos: <b id="manual-convocacao-count">${total}</b></span></div>
  <footer class="manual-convocacao-footer"><span>Marque pelo menos um titular. Titulares vão ao campo; reservas ficam na lista lateral.</span><div class="manual-convocacao-confirm-tools"><label class="manual-convocacao-uniforme-label" for="manual-convocacao-uniforme"><span>Uniforme</span><select id="manual-convocacao-uniforme" aria-label="Escolher uniforme"><option value="base_vermelha" ${st.uniforme==='base_vermelha'?'selected':''}>Base Vermelha</option><option value="base_branca" ${st.uniforme==='base_branca'?'selected':''}>Base Branca</option><option value="base_preta_branca" ${st.uniforme==='base_preta_branca'?'selected':''}>Base Preta/Branca</option></select></label><button type="button" class="manual-convocacao-confirm" onclick="manualConvocacaoConfirmar()">Confirmar Convocação</button></div></footer>
 </div>`;
 modal.querySelectorAll('.manual-convocacao-name').forEach(input=>input.addEventListener('input',()=>manualConvocacaoAtualizarCampoLista(input.dataset.manualId,'nome',input.value)));
 modal.querySelectorAll('.manual-convocacao-number').forEach(input=>input.addEventListener('input',()=>manualConvocacaoAtualizarCampoLista(input.dataset.manualId,'numero',input.value)));
 modal.querySelectorAll('.manual-convocacao-status').forEach(input=>input.addEventListener('change',()=>manualConvocacaoAtualizarCampoLista(input.dataset.manualId,'status',input.value)));
 const uniformeSelect=modal.querySelector('#manual-convocacao-uniforme');
 uniformeSelect?.addEventListener('change',()=>manualConvocacaoAtualizarUniforme(uniformeSelect.value));
 modal.querySelectorAll('[data-manual-remove]').forEach(btn=>btn.addEventListener('click',()=>manualConvocacaoRemoverAtleta(btn.dataset.manualRemove)));
}
function manualConvocacaoAtualizarCampoLista(id,campo,valor){
 const st=manualConvocacaoObterEstado();
 const atleta=st.atletas.find(a=>a.id===id);
 if(!atleta || !['nome','numero','status'].includes(campo))return;
 if(campo==='status')atleta.status=valor==='titular'?'titular':'reserva';
 else atleta[campo]=String(valor||'').trimStart();
 manualConvocacaoSalvarRascunho();
 const count=document.getElementById('manual-convocacao-count');
 if(count)count.textContent=String(st.atletas.filter(a=>a.nome.trim()||a.numero.trim()).length);
}
function manualConvocacaoAtualizarUniforme(valor){
 const st=manualConvocacaoObterEstado();
 const permitido=['base_vermelha','base_branca','base_preta_branca'];
 st.uniforme=permitido.includes(String(valor||'').toLowerCase())?String(valor).toLowerCase():'base_vermelha';
 manualConvocacaoSalvarRascunho();
}
function manualConvocacaoAdicionarAtleta(){
 const st=manualConvocacaoObterEstado();
 const atleta={id:manualConvocacaoNovoId(),nome:'',numero:'',status:'reserva',left:'',top:''};
 st.atletas.push(atleta);manualConvocacaoSalvarRascunho();manualConvocacaoRenderizarLista();
 const inputs=document.querySelectorAll('#convocacao-manual-modal .manual-convocacao-name');
 inputs[inputs.length-1]?.focus();
}
function manualConvocacaoRemoverAtleta(id){
 const st=manualConvocacaoObterEstado();
 st.atletas=st.atletas.filter(a=>a.id!==id);
 manualConvocacaoSalvarRascunho();manualConvocacaoRenderizarLista();
}
function manualConvocacaoLimpar(){
 if(!confirm('Limpar todos os nomes e números desta convocação manual? As convocações salvas não serão excluídas.'))return;
 manualConvocacaoState=manualConvocacaoEstadoInicial();
 manualConvocacaoSalvarRascunho();manualConvocacaoRenderizarLista();
}
function manualConvocacaoConfirmar(){
 const st=manualConvocacaoObterEstado();
 const informados=st.atletas.filter(a=>a.nome.trim()||a.numero.trim());
 if(!informados.length){alert('Digite pelo menos um nome e número de camiseta.');return;}
 const incompleto=informados.find(a=>!a.nome.trim()||!a.numero.trim());
 if(incompleto){alert('Preencha o nome e o número da camiseta de cada atleta informado.');return;}
 const invalido=informados.find(a=>!/^\d{1,2}$/.test(a.numero)||Number(a.numero)<1||Number(a.numero)>99);
 if(invalido){alert('O número da camiseta deve estar entre 1 e 99.');return;}
 if(!informados.some(a=>a.status==='titular')){alert('Marque pelo menos um atleta como titular para abrir o campo.');return;}
 st.atletas=informados.map(a=>({...a,nome:a.nome.trim(),numero:String(Number(a.numero)),status:a.status==='titular'?'titular':'reserva'}));
 manualConvocacaoSalvarRascunho();
 manualConvocacaoAbrirCampo();
}
function manualConvocacaoAbrirCampo(){
 let modal=document.getElementById('campo-convocacao-manual-modal');
 if(modal && modal.style.display!=='none')manualConvocacaoCapturarCampo();
 const st=manualConvocacaoObterEstado();
 if(!modal){modal=document.createElement('div');modal.id='campo-convocacao-manual-modal';modal.className='campo-overlay';document.body.appendChild(modal);}
 const titulares=st.atletas.filter(a=>a.status==='titular');
 const reservas=st.atletas.filter(a=>a.status!=='titular').sort((a,b)=>(Number(a.numero)||999)-(Number(b.numero)||999));
 const titularMarkup=titulares.map((a,i)=>{
  const base=typeof posicaoInicialCampo==='function'?posicaoInicialCampo(a.numero,i):[50,50];
  const left=manualConvocacaoCoord(a.left)||base[0]+'%';
  const top=manualConvocacaoCoord(a.top)||base[1]+'%';
  const uniforme=st.uniforme||'base_vermelha';
  const camisaGoleiro='camiseta_goleiro.png';
  const camisaLinha={
   base_vermelha:'camiseta_linha.png',
   base_branca:'camiseta_linha_2.png',
   base_preta_branca:'camiseta_linha_3.png',
  }[uniforme]||'camiseta_linha.png';
  const camisa=Number(a.numero)===1?camisaGoleiro:camisaLinha;
  return `<div class="jogador-campo" data-manual-player="${manualConvocacaoEscapar(a.id)}" style="left:${left};top:${top}" aria-label="${manualConvocacaoEscapar(a.numero+' '+a.nome)}"><img src="${camisa}" alt=""><span>${manualConvocacaoEscapar(a.numero)} ${manualConvocacaoEscapar(a.nome)}</span></div>`;
 }).join('');
 const reservaMarkup=reservas.map(a=>`<div class="reserva-item"><span>${manualConvocacaoEscapar(a.numero)} - ${manualConvocacaoEscapar(a.nome)}</span><span class="reserva-data"></span></div>`).join('');
 const comissaoLabels=['Técnico:','Aux. Técnico:','Prep. Físico:','Trein. Goleiros:'];
 const comissaoMarkup=comissaoLabels.map((label,i)=>`<label class="comissao-label">${label}<input class="campo-edit" data-manual-commission="${i}" placeholder="" value="${manualConvocacaoEscapar(st.comissao[i]||'')}"></label>`).join('');
 const jogo=st.jogo;
 modal.innerHTML=`<div class="campo-card"><span class="vb-brand-corner campo-brand-corner">VBolonheze Sports</span><div class="campo-top"><b>CONVOCAÇÃO MANUAL — ESCALAÇÃO</b><div class="campo-acoes"><button type="button" onclick="manualConvocacaoAbrirSalvar()">💾 Salvar Convocação</button><button type="button" onclick="manualConvocacaoImprimirCampo()">🖨 Imprimir</button><button type="button" onclick="manualConvocacaoAbrirMinutagem()">⏱ Minutagem</button><button type="button" onclick="manualConvocacaoAbrirArbitragem()">⚖ Arbitragem</button><button type="button" class="campo-fechar" aria-label="Fechar campo" onclick="manualConvocacaoFecharCampo()">×</button></div></div><div class="campo-layout"><aside><h3>SUPLENTES</h3><div class="campo-reservas">${reservaMarkup}</div><h3>COMISSÃO TÉCNICA</h3>${comissaoMarkup}</aside><main><div class="campo-futebol"><div class="linha-meio"></div><div class="circulo-meio"></div>${titularMarkup}</div><div class="campo-detalhes"><div class="campo-faixa"><input data-manual-game="horario" placeholder="Horário" value="${manualConvocacaoEscapar(jogo.horario)}"><span> - </span><input data-manual-game="local" placeholder="Local" value="${manualConvocacaoEscapar(jogo.local)}"><span> - </span><input data-manual-game="data" placeholder="Data" value="${manualConvocacaoEscapar(jogo.data)}"></div><div class="campo-info-jogo"><div class="campo-adversario"><img src="sa-logo.svg" alt="VBolonheze Sports"><b>×</b><input data-manual-game="adversario" placeholder="Nome do adversário" value="${manualConvocacaoEscapar(jogo.adversario)}"></div><div class="campo-horarios"><label>Apresentação: <input data-manual-game="apresentacao" placeholder="" value="${manualConvocacaoEscapar(jogo.apresentacao)}"></label><label>Preleção: <input data-manual-game="prelecao" placeholder="" value="${manualConvocacaoEscapar(jogo.prelecao)}"></label><label>Aquecimento: <input data-manual-game="aquecimento" placeholder="" value="${manualConvocacaoEscapar(jogo.aquecimento)}"></label></div></div></div></main></div></div>`;
 modal.style.display='flex';
 modal.querySelectorAll('.jogador-campo').forEach(el=>{
  if(typeof makeCampoDraggable==='function')makeCampoDraggable(el);
  el.addEventListener('pointerup',manualConvocacaoCapturarCampo);
  el.addEventListener('pointercancel',manualConvocacaoCapturarCampo);
 });
 modal.querySelectorAll('[data-manual-game],[data-manual-commission]').forEach(el=>el.addEventListener('input',manualConvocacaoCapturarCampo));
 manualConvocacaoSalvarRascunho();
}
function manualConvocacaoCapturarCampo(){
 const modal=document.getElementById('campo-convocacao-manual-modal');
 const card=modal?.querySelector('.campo-card');
 const st=manualConvocacaoState;
 if(!card||!st)return;
 const game={};
 card.querySelectorAll('[data-manual-game]').forEach(el=>{game[el.dataset.manualGame]=el.value;});
 st.jogo={
  horario:game.horario||'',local:game.local||'',data:game.data||'',adversario:game.adversario||'',
  apresentacao:game.apresentacao||'',prelecao:game.prelecao||'',aquecimento:game.aquecimento||''
 };
 card.querySelectorAll('[data-manual-commission]').forEach(el=>{const i=Number(el.dataset.manualCommission);if(i>=0&&i<4)st.comissao[i]=el.value;});
 card.querySelectorAll('.jogador-campo[data-manual-player]').forEach(el=>{
  const atleta=st.atletas.find(a=>a.id===el.dataset.manualPlayer);
  if(atleta){atleta.left=manualConvocacaoCoord(el.style.left);atleta.top=manualConvocacaoCoord(el.style.top);}
 });
 manualConvocacaoSalvarRascunho();
}
function manualConvocacaoFecharCampo(){
 manualConvocacaoCapturarCampo();
 const modal=document.getElementById('campo-convocacao-manual-modal');if(modal)modal.style.display='none';
}
function manualConvocacaoImprimirCampo(){
 const modal=document.getElementById('campo-convocacao-manual-modal');
 const card=modal?.querySelector('.campo-card');
 if(!modal||!card)return;
 manualConvocacaoCapturarCampo();
 if(typeof saIsMobile==='function'&&saIsMobile()&&typeof saCompartilharOuSalvarPDF==='function'){
  saCompartilharOuSalvarPDF(card,'convocacao_manual_vbolonheze_sports','landscape','convocacao-campo','Convocação Manual VBolonheze Sports');
  return;
 }
 const layout=document.createElement('div');layout.id='print-convocacao-layout';
 layout.innerHTML='<img class="print-base" src="BASE limpa.png" onerror="this.onerror=null;this.src=&quot;BASE%20CAMPO.png&quot;"><div class="vb-brand-corner print-brand-corner">VBolonheze Sports</div><div class="print-title">CONVOCAÇÃO MANUAL — ESCALAÇÃO</div><div class="print-side"></div><div class="print-bottom"></div><div class="print-players"></div>';
 const side=layout.querySelector('.print-side');
 const aside=card.querySelector('aside');
 if(aside){
  side.innerHTML=aside.innerHTML;
  const origem=[...aside.querySelectorAll('input')],destino=[...side.querySelectorAll('input')];
  origem.forEach((x,i)=>{if(destino[i])destino[i].value=x.value;});
 }
 const bottom=layout.querySelector('.print-bottom');
 const details=card.querySelector('.campo-detalhes');
 if(details){
  bottom.innerHTML=details.innerHTML;
  const origem=[...details.querySelectorAll('input')],destino=[...bottom.querySelectorAll('input')];
  origem.forEach((x,i)=>{if(destino[i])destino[i].value=x.value;});
 }
 const campo=card.querySelector('.campo-futebol');
 if(!campo)return;
 const rc=campo.getBoundingClientRect(),rCard=card.getBoundingClientRect();
 card.querySelectorAll('.jogador-campo').forEach(p=>{
  const q=p.cloneNode(true),r=p.getBoundingClientRect();
  q.style.left=(((r.left+r.width/2-rCard.left)/rCard.width)*100)+'%';
  q.style.top=(((r.top+r.height/2-rCard.top)/rCard.height)*100)+'%';
  layout.querySelector('.print-players').appendChild(q);
 });
 document.body.appendChild(layout);document.body.classList.add('printing-dedicated-convocacao');
 const clean=()=>{document.body.classList.remove('printing-dedicated-convocacao');layout.remove();window.removeEventListener('afterprint',clean);};
 window.addEventListener('afterprint',clean);window.print();setTimeout(clean,1500);
}
function manualConvocacaoMensagemTabela(error,acao){
 const msg=String(error?.message||error||'');
 if(/42P01|does not exist|not found|schema cache|could not find the table/i.test(msg)){
  alert(`Não foi possível preparar a Convocação Manual no armazenamento local. Tente ${acao} novamente.`);
 }else{
  alert(`Não foi possível ${acao} a convocação manual. Confira o armazenamento local e tente novamente.`);
 }
 console.error(`Convocação manual — erro ao ${acao}:`,error);
}
async function manualConvocacaoAbrirCarregar(){
 try{
  const {data,error}=await _saData.from(MANUAL_CONVOCACAO_TABLE).select('nome').order('nome',{ascending:true});
  if(error){manualConvocacaoMensagemTabela(error,'consultar');return;}
  if(!data||!data.length){alert('Nenhuma convocação manual salva.');return;}
  let modal=document.getElementById('manual-convocacao-carregar-modal');
  if(!modal){modal=document.createElement('div');modal.id='manual-convocacao-carregar-modal';modal.className='escalacao-overlay';document.body.appendChild(modal);}
  const options=data.map(x=>`<option value="${manualConvocacaoEscapar(x.nome)}">${manualConvocacaoEscapar(x.nome)}</option>`).join('');
  modal.innerHTML=`<div class="excluir-card manual-convocacao-picker-card"><h3>Carregar convocação manual</h3><p>Selecione uma lista manual salva:</p><select id="manual-convocacao-para-carregar" size="9">${options}</select><div><button type="button" class="carregar-btn" onclick="manualConvocacaoConfirmarCarregamento()">Carregar</button><button type="button" onclick="document.getElementById('manual-convocacao-carregar-modal').style.display='none'">Cancelar</button></div></div>`;
  modal.style.display='flex';
 }catch(error){manualConvocacaoMensagemTabela(error,'consultar');}
}
async function manualConvocacaoConfirmarCarregamento(){
 const select=document.getElementById('manual-convocacao-para-carregar');
 if(!select?.value){alert('Selecione uma convocação manual.');return;}
 try{
  const {data,error}=await _saData.from(MANUAL_CONVOCACAO_TABLE).select('nome,dados').eq('nome',select.value).single();
  if(error||!data){manualConvocacaoMensagemTabela(error||'Registro não encontrado','carregar');return;}
  let payload=data.dados||{};
  if(typeof payload==='string'){try{payload=JSON.parse(payload);}catch(e){payload={};}}
  const loaded=manualConvocacaoNormalizarEstado({...payload,salvoComo:data.nome});
  if(!loaded.atletas.length){alert('A convocação salva não contém atletas.');return;}
  manualConvocacaoState=loaded;manualConvocacaoSalvarRascunho();
  const modal=document.getElementById('manual-convocacao-carregar-modal');if(modal)modal.style.display='none';
  manualConvocacaoRenderizarLista();
 }catch(error){manualConvocacaoMensagemTabela(error,'carregar');}
}
async function manualConvocacaoAbrirExcluir(){
 try{
  const {data,error}=await _saData.from(MANUAL_CONVOCACAO_TABLE).select('nome').order('nome',{ascending:true});
  if(error){manualConvocacaoMensagemTabela(error,'consultar');return;}
  if(!data||!data.length){alert('Nenhuma convocação manual salva para excluir.');return;}
  let modal=document.getElementById('manual-convocacao-excluir-modal');
  if(!modal){modal=document.createElement('div');modal.id='manual-convocacao-excluir-modal';modal.className='escalacao-overlay';document.body.appendChild(modal);}
  const options=data.map(x=>`<option value="${manualConvocacaoEscapar(x.nome)}">${manualConvocacaoEscapar(x.nome)}</option>`).join('');
  modal.innerHTML=`<div class="excluir-card manual-convocacao-picker-card"><h3>Excluir convocação manual</h3><p>Escolha a lista manual que deseja apagar permanentemente:</p><select id="manual-convocacao-para-excluir" size="9">${options}</select><div><button type="button" onclick="manualConvocacaoExcluirSelecionada()">Excluir</button><button type="button" onclick="document.getElementById('manual-convocacao-excluir-modal').style.display='none'">Cancelar</button></div></div>`;
  modal.style.display='flex';
 }catch(error){manualConvocacaoMensagemTabela(error,'consultar');}
}
async function manualConvocacaoExcluirSelecionada(){
 const select=document.getElementById('manual-convocacao-para-excluir');
 if(!select?.value){alert('Selecione uma convocação manual.');return;}
 const nome=select.value;
 if(!confirm(`Excluir “${nome}” permanentemente? Esta ação só afeta as convocações manuais.`))return;
 try{
  const {error}=await _saData.from(MANUAL_CONVOCACAO_TABLE).delete().eq('nome',nome);
  if(error){manualConvocacaoMensagemTabela(error,'excluir');return;}
  if(manualConvocacaoState?.salvoComo===nome){manualConvocacaoState.salvoComo='';manualConvocacaoSalvarRascunho();manualConvocacaoRenderizarLista();}
  const modal=document.getElementById('manual-convocacao-excluir-modal');if(modal)modal.style.display='none';
  alert('Convocação manual excluída.');
 }catch(error){manualConvocacaoMensagemTabela(error,'excluir');}
}
async function manualConvocacaoAbrirSalvar(){
 manualConvocacaoCapturarCampo();
 try{
  const {data,error}=await _saData.from(MANUAL_CONVOCACAO_TABLE).select('nome').order('nome',{ascending:true});
  if(error){manualConvocacaoMensagemTabela(error,'consultar');return;}
  let modal=document.getElementById('manual-convocacao-salvar-modal');
  if(!modal){modal=document.createElement('div');modal.id='manual-convocacao-salvar-modal';modal.className='escalacao-overlay';document.body.appendChild(modal);}
  const options=(data||[]).map(x=>`<option value="${manualConvocacaoEscapar(x.nome)}">${manualConvocacaoEscapar(x.nome)}</option>`).join('');
  modal.innerHTML=`<div class="excluir-card salvar-card manual-convocacao-picker-card"><h3>Salvar convocação manual</h3><p>Digite um nome novo ou selecione uma convocação manual para substituir.</p><input id="manual-nome-nova-convocacao" class="nome-convocacao-input" maxlength="120" placeholder="Nome da convocação" value="${manualConvocacaoEscapar(manualConvocacaoState?.salvoComo||'')}"><select id="manual-convocacao-para-substituir" size="7"><option value="">— Nova convocação —</option>${options}</select><div><button type="button" class="carregar-btn" onclick="manualConvocacaoConfirmarSalvar()">Salvar</button><button type="button" onclick="document.getElementById('manual-convocacao-salvar-modal').style.display='none'">Cancelar</button></div></div>`;
  const select=modal.querySelector('#manual-convocacao-para-substituir');
  select?.addEventListener('change',()=>{if(select.value)modal.querySelector('#manual-nome-nova-convocacao').value=select.value;});
  modal.style.display='flex';
 }catch(error){manualConvocacaoMensagemTabela(error,'consultar');}
}
async function manualConvocacaoConfirmarSalvar(){
 const input=document.getElementById('manual-nome-nova-convocacao');
 const nome=String(input?.value||'').trim();
 if(!nome){alert('Digite um nome para esta convocação manual.');return;}
 manualConvocacaoCapturarCampo();
 const st=manualConvocacaoObterEstado();
 const dados={
  tipo:'manual',versao:1,salvoComo:nome,uniforme:st.uniforme||'base',
  atletas:st.atletas.map(a=>({id:a.id,nome:a.nome,numero:a.numero,status:a.status,left:a.left||'',top:a.top||''})),
  jogo:{...st.jogo},comissao:[...st.comissao]
 };
 try{
  const {error}=await _saData.from(MANUAL_CONVOCACAO_TABLE).upsert({nome,dados,atualizado_em:new Date().toISOString()},{onConflict:'nome'});
  if(error){manualConvocacaoMensagemTabela(error,'salvar');return;}
  st.salvoComo=nome;manualConvocacaoSalvarRascunho();
  const modal=document.getElementById('manual-convocacao-salvar-modal');if(modal)modal.style.display='none';
  manualConvocacaoRenderizarLista();
  alert('Convocação manual salva com sucesso.');
 }catch(error){manualConvocacaoMensagemTabela(error,'salvar');}
}
function manualConvocacaoAbrirArbitragem(){
 const st=manualConvocacaoObterEstado();manualConvocacaoCapturarCampo();
 const lista=[...st.atletas].sort((a,b)=>String(a.nome).localeCompare(String(b.nome),'pt-BR'));
 const logo=saSiteEscape(saSiteCurrentLogoSrc());
 const w=window.open('','_blank','width=800,height=800');if(!w){alert('Permita pop-ups para imprimir a ficha de arbitragem.');return;}
 const linhas=lista.map(a=>`<tr><td>${manualConvocacaoEscapar(a.numero)}</td><td>${manualConvocacaoEscapar(a.nome)}</td><td></td><td></td></tr>`).join('');
 w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Arbitragem — Convocação Manual</title><style>@page{size:A4 portrait;margin:8mm}*{box-sizing:border-box}body{font-family:Arial;margin:0}.vb-brand-corner{position:absolute;top:4px;right:6px;z-index:8;display:inline-block;padding:3px 7px;border:1px solid #40b8a8;border-radius:999px;background:#fff;color:#173b59;font:800 9px/1.2 Arial,sans-serif;white-space:nowrap}.ficha{position:relative;border:1px solid #111;min-height:0;height:auto}.cab{height:38mm;border-bottom:1px solid #111;display:flex;align-items:center;padding:8px 40mm 8px 20px;gap:100px}.cab img{width:32mm;height:32mm;object-fit:contain}.cab h1{font-size:25px;margin:0}.tab{width:100%;border-collapse:collapse;table-layout:fixed;font-size:10px}.tab th{text-align:left;border-bottom:1px solid #111;padding:4px}.tab td{height:15px;border-bottom:1px dotted #111;border-right:1px dotted #111;padding:2px 4px}.tab th:nth-child(1),.tab td:nth-child(1){width:11%;font-weight:bold}.tab th:nth-child(2),.tab td:nth-child(2){width:46%;font-weight:bold}.tab th:nth-child(3),.tab td:nth-child(3){width:23%}.tab th:nth-child(4),.tab td:nth-child(4){width:20%}</style></head><body><div class="ficha"><div class="vb-brand-corner">VBolonheze Sports</div><div class="cab"><img src="${logo}"><h1>ARBITRAGEM — CONVOCAÇÃO MANUAL</h1></div><table class="tab"><thead><tr><th>Número</th><th>Nome Completo</th><th>Apelido</th><th>Data Nasc.</th></tr></thead><tbody>${linhas}</tbody></table></div><script>window.onload=()=>setTimeout(()=>window.print(),500)<\/script></body></html>`);
 w.document.close();
}
function manualConvocacaoAbrirMinutagem(){
 const st=manualConvocacaoObterEstado();manualConvocacaoCapturarCampo();
 const adv=st.jogo.adversario||'';const data=st.jogo.data||'';
 const arr=st.atletas.map(a=>({n:a.numero||'',nome:a.nome||'',res:a.status==='reserva'}));
 const titulares=arr.filter(x=>!x.res).sort((a,b)=>(Number(a.n)||999)-(Number(b.n)||999));
 const suplentes=arr.filter(x=>x.res).sort((a,b)=>(Number(a.n)||999)-(Number(b.n)||999));
 const linha=x=>`<tr><td>${manualConvocacaoEscapar(x.n)}</td><td>${manualConvocacaoEscapar(x.nome)}</td><td></td><td class="box"></td><td class="box"></td><td class="tempo-box"></td><td class="minuto"></td><td class="tempo-box"></td><td></td><td></td><td class="box"></td><td class="box"></td></tr>`;
 const supl=suplentes.map(x=>`<tr><td>${manualConvocacaoEscapar(x.n)}</td><td>${manualConvocacaoEscapar(x.nome)}</td></tr>`).join('');
 const logo=saSiteEscape(saSiteCurrentLogoSrc());
 const w=window.open('','_blank','width=1100,height=800');if(!w){alert('Permita pop-ups para imprimir a minutagem.');return;}
 w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Minutagem — Convocação Manual</title><style>@page{size:A4 landscape;margin:10mm}*{box-sizing:border-box}body{font-family:Arial;margin:0;font-size:12px;position:relative}.vb-brand-corner{position:absolute;top:1px;right:1px;z-index:8;display:inline-block;padding:3px 7px;border:1px solid #40b8a8;border-radius:999px;background:#fff;color:#173b59;font:800 9px/1.2 Arial,sans-serif;white-space:nowrap}.head{height:92px;display:flex;align-items:center;justify-content:center;gap:35px}.head img{width:82px}.sq{width:64px;height:38px;border:3px solid #111}.x{font-size:34px;font-weight:bold}.adv{font-size:22px;font-weight:bold}.tbl{width:100%;border-collapse:collapse;table-layout:fixed}.tbl th{text-align:center;height:23px}.tbl td{height:18px;border:1px solid #111;padding:1px 4px}.tbl td:nth-child(1){width:52px;text-align:center;border-right:0}.tbl td:nth-child(2){width:180px;text-align:left}.tbl td:nth-child(3){width:55px}.tbl td:nth-child(4),.tbl td:nth-child(5),.tbl td:nth-child(9),.tbl td:nth-child(10){width:62px}.tbl td.box,.tbl td.tempo-box,.tbl td.minuto{border:1px solid #111!important;background:#fff;height:16px}.tbl th:nth-child(1),.tbl td:nth-child(1){font-size:10px!important;width:32px!important;min-width:32px!important;max-width:32px!important;text-align:center!important}.tbl td:nth-child(7),.tbl th:nth-child(7){text-align:center!important}.tbl th:nth-child(3),.tbl td:nth-child(3),.tbl th:nth-child(10),.tbl td:nth-child(10){width:42px!important;min-width:42px!important;max-width:42px!important;padding:1px!important;text-align:center!important;white-space:nowrap}.tbl th:nth-child(4),.tbl td:nth-child(4),.tbl th:nth-child(5),.tbl td:nth-child(5),.tbl th:nth-child(11),.tbl td:nth-child(11),.tbl th:nth-child(12),.tbl td:nth-child(12){width:40px!important;min-width:40px!important;max-width:40px!important;padding:1px!important;text-align:center!important;white-space:nowrap}.tbl th:nth-child(6),.tbl td:nth-child(6),.tbl th:nth-child(8),.tbl td:nth-child(8){width:32px!important;min-width:32px!important;max-width:32px!important;padding:1px!important;text-align:center!important;white-space:nowrap}.tbl th:nth-child(7),.tbl td:nth-child(7){width:58px!important;min-width:58px!important;max-width:58px!important;text-align:center!important}.ca{background:#ff0}.cv{color:red}.bar{background:#c00;color:#fff;text-align:center;font-weight:bold;height:18px}.bottom{display:grid;grid-template-columns:240px 1fr;gap:60px}.sup td{height:15px;border-bottom:1px solid #111;border-right:2px dotted #111}.info{margin-top:15px;font-size:20px;text-align:center}.check{display:inline-block;width:36px;height:34px;border:2px solid #e33;vertical-align:middle;margin:8px 15px}.notes{border:3px solid #111;height:90px;margin-top:0;padding:4px;font-size:12px}</style></head><body><div class="vb-brand-corner">VBolonheze Sports</div><div class="head"><img src="${logo}"><span class="sq"></span><span class="x">X</span><span class="sq"></span><span class="adv">${manualConvocacaoEscapar(adv||'Adversário')}</span></div><table class="tbl"><thead><tr><th>Número</th><th>Titulares</th><th>Gols</th><th class="ca">C.A.</th><th class="cv">C.V.</th><th>1º</th><th>Minuto</th><th>2º</th><th>Suplentes</th><th>Gols</th><th class="ca">C.A.</th><th class="cv">C.V.</th></tr></thead><tbody>${titulares.map(linha).join('')}<tr><td colspan="12" class="bar">Suplentes</td></tr></tbody></table><div class="bottom"><table class="sup"><tbody>${supl}</tbody></table><div><div class="info"><b>Data:</b> ${manualConvocacaoEscapar(data||'____/____/______')}<br><span class="check"></span> Casa <span class="check"></span> Fora</div><div class="notes">Informações adicionais</div></div></div><script>window.onload=()=>setTimeout(()=>window.print(),500)<\/script></body></html>`);
 w.document.close();
}
